package handlers

import (
	"net/http"

	"educabot.com/bookshop/services"
	"educabot.com/bookshop/utils"
	"github.com/gin-gonic/gin"
)

// GetMetricsRequest define los parámetros de query aceptados por el endpoint
type GetMetricsRequest struct {
	Author string `form:"author"`
}

// GetMetrics es el handler HTTP para el endpoint de métricas de libros
// Siguiendo el principio de Responsabilidad Única (SRP), solo maneja HTTP:
// - Validación de entrada
// - Orquestación de servicios
// - Serialización de respuesta
type GetMetrics struct {
	booksService services.BooksService
}

// NewGetMetrics crea un nuevo handler inyectando el servicio de libros
// Usa inyección de dependencias para facilitar testing y seguir el principio DIP
func NewGetMetrics(booksService services.BooksService) GetMetrics {
	return GetMetrics{booksService}
}

// Handle retorna el handler function para Gin
// Delega toda la lógica de negocio al servicio, manteniendo el handler simple
func (h GetMetrics) Handle() gin.HandlerFunc {
	return func(ctx *gin.Context) {
		// Validar y parsear los parámetros de query
		var query GetMetricsRequest
		if err := ctx.ShouldBindQuery(&query); err != nil {
			utils.RespondWithBadRequest(ctx, "Invalid query parameters: "+err.Error())
			return
		}

		// Obtener métricas usando el servicio (lógica de negocio)
		meanUnitsSold, err := h.booksService.GetMeanUnitsSold(ctx.Request.Context())
		if err != nil {
			utils.RespondWithInternalError(ctx, "Failed to calculate mean units sold: "+err.Error())
			return
		}

		cheapestBook, err := h.booksService.GetCheapestBook(ctx.Request.Context())
		if err != nil {
			utils.RespondWithInternalError(ctx, "Failed to find cheapest book: "+err.Error())
			return
		}

		booksWrittenByAuthor, err := h.booksService.CountBooksByAuthor(ctx.Request.Context(), query.Author)
		if err != nil {
			utils.RespondWithInternalError(ctx, "Failed to count books by author: "+err.Error())
			return
		}

		// Responder con los datos en formato JSON
		ctx.JSON(http.StatusOK, map[string]interface{}{
			"mean_units_sold":         meanUnitsSold,
			"cheapest_book":           cheapestBook,
			"books_written_by_author": booksWrittenByAuthor,
		})
	}
}

package main

import (
	"fmt"

	"educabot.com/bookshop/handlers"
	"educabot.com/bookshop/providers"
	"educabot.com/bookshop/services"
	"github.com/gin-gonic/gin"
)

func main() {
	router := gin.New()
	router.SetTrustedProxies(nil)

	// Inyección de dependencias siguiendo el patrón de arquitectura en capas:
	// Provider -> Service -> Handler
	// Esto sigue el principio de Inversión de Dependencias (DIP)

	// Capa de Provider: obtiene datos de fuentes externas (API HTTP)
	booksProvider := providers.NewHTTPBooksProvider()

	// Capa de Service: contiene la lógica de negocio
	booksService := services.NewBooksService(booksProvider)

	// Capa de Handler: maneja HTTP y orquesta servicios
	metricsHandler := handlers.NewGetMetrics(booksService)

	router.GET("/", metricsHandler.Handle())

	fmt.Println("Starting server on :3000")
	router.Run(":3000")
}

package handlers

import (
	"context"
	"encoding/json"
	"errors"
	"net/http"
	"net/http/httptest"
	"testing"

	"educabot.com/bookshop/models"
	"educabot.com/bookshop/services"
	"github.com/gin-gonic/gin"
	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/mock"
)

// MockBooksService es un mock del servicio de libros para testing
type MockBooksService struct {
	mock.Mock
}

func (m *MockBooksService) GetMeanUnitsSold(ctx context.Context) (uint, error) {
	args := m.Called(ctx)
	return args.Get(0).(uint), args.Error(1)
}

func (m *MockBooksService) GetCheapestBook(ctx context.Context) (string, error) {
	args := m.Called(ctx)
	return args.String(0), args.Error(1)
}

func (m *MockBooksService) CountBooksByAuthor(ctx context.Context, author string) (uint, error) {
	args := m.Called(ctx, author)
	return args.Get(0).(uint), args.Error(1)
}

func TestGetMetrics_OK(t *testing.T) {
	gin.SetMode(gin.TestMode)

	// Arrange
	mockService := new(MockBooksService)
	mockService.On("GetMeanUnitsSold", mock.Anything).Return(uint(11000), nil)
	mockService.On("GetCheapestBook", mock.Anything).Return("The Go Programming Language", nil)
	mockService.On("CountBooksByAuthor", mock.Anything, "Alan Donovan").Return(uint(1), nil)

	handler := NewGetMetrics(mockService)
	r := gin.Default()
	r.GET("/", handler.Handle())

	// Act
	req := httptest.NewRequest(http.MethodGet, "/?author=Alan+Donovan", nil)
	res := httptest.NewRecorder()
	r.ServeHTTP(res, req)

	// Assert
	var resBody map[string]interface{}
	json.Unmarshal(res.Body.Bytes(), &resBody)

	assert.Equal(t, http.StatusOK, res.Code)
	assert.Equal(t, 11000, int(resBody["mean_units_sold"].(float64)))
	assert.Equal(t, "The Go Programming Language", resBody["cheapest_book"])
	assert.Equal(t, 1, int(resBody["books_written_by_author"].(float64)))
	mockService.AssertExpectations(t)
}

func TestGetMetrics_WithoutAuthorParameter(t *testing.T) {
	gin.SetMode(gin.TestMode)

	// Arrange
	mockService := new(MockBooksService)
	mockService.On("GetMeanUnitsSold", mock.Anything).Return(uint(50000), nil)
	mockService.On("GetCheapestBook", mock.Anything).Return("Some Book", nil)
	mockService.On("CountBooksByAuthor", mock.Anything, "").Return(uint(0), nil)

	handler := NewGetMetrics(mockService)
	r := gin.Default()
	r.GET("/", handler.Handle())

	// Act
	req := httptest.NewRequest(http.MethodGet, "/", nil)
	res := httptest.NewRecorder()
	r.ServeHTTP(res, req)

	// Assert
	var resBody map[string]interface{}
	json.Unmarshal(res.Body.Bytes(), &resBody)

	assert.Equal(t, http.StatusOK, res.Code)
	assert.Equal(t, 50000, int(resBody["mean_units_sold"].(float64)))
	assert.Equal(t, "Some Book", resBody["cheapest_book"])
	assert.Equal(t, 0, int(resBody["books_written_by_author"].(float64)))
	mockService.AssertExpectations(t)
}

func TestGetMetrics_ServiceError_MeanUnitsSold(t *testing.T) {
	gin.SetMode(gin.TestMode)

	// Arrange
	mockService := new(MockBooksService)
	mockService.On("GetMeanUnitsSold", mock.Anything).Return(uint(0), services.ErrNoBooksAvailable)

	handler := NewGetMetrics(mockService)
	r := gin.Default()
	r.GET("/", handler.Handle())

	// Act
	req := httptest.NewRequest(http.MethodGet, "/?author=Test", nil)
	res := httptest.NewRecorder()
	r.ServeHTTP(res, req)

	// Assert
	var resBody map[string]interface{}
	json.Unmarshal(res.Body.Bytes(), &resBody)

	assert.Equal(t, http.StatusInternalServerError, res.Code)
	assert.Contains(t, resBody["error"], "internal_error")
	assert.Contains(t, resBody["message"], "Failed to calculate mean units sold")
	mockService.AssertExpectations(t)
}

func TestGetMetrics_ServiceError_CheapestBook(t *testing.T) {
	gin.SetMode(gin.TestMode)

	// Arrange
	mockService := new(MockBooksService)
	mockService.On("GetMeanUnitsSold", mock.Anything).Return(uint(100), nil)
	mockService.On("GetCheapestBook", mock.Anything).Return("", services.ErrNoBooksAvailable)

	handler := NewGetMetrics(mockService)
	r := gin.Default()
	r.GET("/", handler.Handle())

	// Act
	req := httptest.NewRequest(http.MethodGet, "/?author=Test", nil)
	res := httptest.NewRecorder()
	r.ServeHTTP(res, req)

	// Assert
	var resBody map[string]interface{}
	json.Unmarshal(res.Body.Bytes(), &resBody)

	assert.Equal(t, http.StatusInternalServerError, res.Code)
	assert.Contains(t, resBody["error"], "internal_error")
	assert.Contains(t, resBody["message"], "Failed to find cheapest book")
	mockService.AssertExpectations(t)
}

func TestGetMetrics_ServiceError_CountBooksByAuthor(t *testing.T) {
	gin.SetMode(gin.TestMode)

	// Arrange
	mockService := new(MockBooksService)
	mockService.On("GetMeanUnitsSold", mock.Anything).Return(uint(100), nil)
	mockService.On("GetCheapestBook", mock.Anything).Return("Book Name", nil)
	mockService.On("CountBooksByAuthor", mock.Anything, "Test").Return(uint(0), errors.New("provider failed"))

	handler := NewGetMetrics(mockService)
	r := gin.Default()
	r.GET("/", handler.Handle())

	// Act
	req := httptest.NewRequest(http.MethodGet, "/?author=Test", nil)
	res := httptest.NewRecorder()
	r.ServeHTTP(res, req)

	// Assert
	var resBody map[string]interface{}
	json.Unmarshal(res.Body.Bytes(), &resBody)

	assert.Equal(t, http.StatusInternalServerError, res.Code)
	assert.Contains(t, resBody["error"], "internal_error")
	assert.Contains(t, resBody["message"], "Failed to count books by author")
	mockService.AssertExpectations(t)
}

// MockBooksProvider para test de integración con datos reales
type TestBooksProvider struct{}

func (p *TestBooksProvider) GetBooks(ctx context.Context) []models.Book {
	return []models.Book{
		{ID: 1, Name: "The Go Programming Language", Author: "Alan Donovan", UnitsSold: 5000, Price: 40},
		{ID: 2, Name: "Clean Code", Author: "Robert C. Martin", UnitsSold: 15000, Price: 50},
		{ID: 3, Name: "The Pragmatic Programmer", Author: "Andrew Hunt", UnitsSold: 13000, Price: 45},
	}
}

func TestGetMetrics_Integration(t *testing.T) {
	gin.SetMode(gin.TestMode)

	// Arrange - Usar implementación real del servicio con un provider de prueba
	provider := &TestBooksProvider{}
	service := services.NewBooksService(provider)
	handler := NewGetMetrics(service)

	r := gin.Default()
	r.GET("/", handler.Handle())

	// Act
	req := httptest.NewRequest(http.MethodGet, "/?author=Alan+Donovan", nil)
	res := httptest.NewRecorder()
	r.ServeHTTP(res, req)

	// Assert
	var resBody map[string]interface{}
	json.Unmarshal(res.Body.Bytes(), &resBody)

	assert.Equal(t, http.StatusOK, res.Code)
	assert.Equal(t, 11000, int(resBody["mean_units_sold"].(float64))) // (5000 + 15000 + 13000) / 3
	assert.Equal(t, "The Go Programming Language", resBody["cheapest_book"]) // Precio 40
	assert.Equal(t, 1, int(resBody["books_written_by_author"].(float64)))
}

