// ErrorResponse representa la estructura estándar de respuesta de error
type ErrorResponse struct {
	Error   string `json:"error"`
	Message string `json:"message"`
}

// RespondWithError envía una respuesta de error estandarizada al cliente
// Centraliza el manejo de errores HTTP para mantener consistencia en toda la API
func RespondWithError(ctx *gin.Context, statusCode int, errorType string, message string) {
	ctx.JSON(statusCode, ErrorResponse{
		Error:   errorType,
		Message: message,
	})
}

// RespondWithBadRequest es un helper para errores 400 Bad Request
func RespondWithBadRequest(ctx *gin.Context, message string) {
	RespondWithError(ctx, http.StatusBadRequest, "bad_request", message)
}

// RespondWithInternalError es un helper para errores 500 Internal Server Error
func RespondWithInternalError(ctx *gin.Context, message string) {
	RespondWithError(ctx, http.StatusInternalServerError, "internal_error", message)
}

// RespondWithServiceUnavailable es un helper para errores 503 Service Unavailable
func RespondWithServiceUnavailable(ctx *gin.Context, message string) {
	RespondWithError(ctx, http.StatusServiceUnavailable, "service_unavailable", message)
}
"}

{"content": "package services

import (
	"context"
	"errors"
	"slices"

	"educabot.com/bookshop/models"
	"educabot.com/bookshop/providers"
)

var (
	// ErrNoBooksAvailable indica que no hay libros disponibles para procesar
	ErrNoBooksAvailable = errors.New("no books available")
	// ErrProviderFailed indica que el provider falló al obtener los libros
	ErrProviderFailed = errors.New("failed to retrieve books from provider")
)

// BooksService define los métodos de negocio relacionados con libros
// Siguiendo el principio de Responsabilidad Única (SRP), este servicio
// se enfoca únicamente en la lógica de negocio, sin preocuparse por HTTP o presentación
type BooksService interface {
	GetMeanUnitsSold(ctx context.Context) (uint, error)
	GetCheapestBook(ctx context.Context) (string, error)
	CountBooksByAuthor(ctx context.Context, author string) (uint, error)
}

// booksService es la implementación concreta de BooksService
type booksService struct {
	booksProvider providers.BooksProvider
}

// NewBooksService crea una nueva instancia del servicio de libros
// Usa inyección de dependencias para recibir el provider, facilitando testing y flexibilidad
func NewBooksService(provider providers.BooksProvider) BooksService {
	return &booksService{
		booksProvider: provider,
	}
}

// GetMeanUnitsSold calcula el promedio de unidades vendidas de todos los libros
// Retorna error si no hay libros disponibles para evitar división por cero
func (s *booksService) GetMeanUnitsSold(ctx context.Context) (uint, error) {
	books := s.booksProvider.GetBooks(ctx)

	if len(books) == 0 {
		return 0, ErrNoBooksAvailable
	}

	var sum uint
	for _, book := range books {
		sum += book.UnitsSold
	}

	return sum / uint(len(books)), nil
}

// GetCheapestBook encuentra el libro con el precio más bajo
// Retorna el nombre del libro más barato o error si no hay libros
func (s *booksService) GetCheapestBook(ctx context.Context) (string, error) {
	books := s.booksProvider.GetBooks(ctx)

	if len(books) == 0 {
		return "", ErrNoBooksAvailable
	}

	cheapest := slices.MinFunc(books, func(a, b models.Book) int {
		return int(a.Price - b.Price)
	})

	return cheapest.Name, nil
}

// CountBooksByAuthor cuenta cuántos libros fueron escritos por un autor específico
// La búsqueda es case-sensitive para mantener consistencia
func (s *booksService) CountBooksByAuthor(ctx context.Context, author string) (uint, error) {
	books := s.booksProvider.GetBooks(ctx)

	var count uint
	for _, book := range books {
		if book.Author == author {
			count++
		}
	}

	return count, nil
}
