{"content": "package services

import (
	"context"
	"testing"

	"educabot.com/bookshop/models"
	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/mock"
)

// MockBooksProvider es un mock del BooksProvider para testing
type MockBooksProvider struct {
	mock.Mock
}

func (m *MockBooksProvider) GetBooks(ctx context.Context) []models.Book {
	args := m.Called(ctx)
	return args.Get(0).([]models.Book)
}

func TestGetMeanUnitsSold_Success(t *testing.T) {
	// Arrange
	mockProvider := new(MockBooksProvider)
	books := []models.Book{
		{ID: 1, Name: "Book 1", Author: "Author 1", UnitsSold: 100, Price: 10},
		{ID: 2, Name: "Book 2", Author: "Author 2", UnitsSold: 200, Price: 20},
		{ID: 3, Name: "Book 3", Author: "Author 3", UnitsSold: 300, Price: 30},
	}
	mockProvider.On("GetBooks", mock.Anything).Return(books)

	service := NewBooksService(mockProvider)
	ctx := context.Background()

	// Act
	result, err := service.GetMeanUnitsSold(ctx)

	// Assert
