package providers

import (
	"context"

	"educabot.com/bookshop/models"
)

// BooksProvider define la interfaz para obtener libros desde diferentes fuentes
// Retorna error para permitir manejo apropiado en capas superiores
type BooksProvider interface {
	GetBooks(ctx context.Context) ([]models.Book, error)
}

// GetBooks obtiene la lista de libros desde el servicio HTTP externo
// El contexto permite cancelación y timeouts a nivel de aplicación
// Retorna error para permitir manejo apropiado en capas superiores
func (p *HTTPBooksProvider) GetBooks(ctx context.Context) ([]models.Book, error) {
	// Crear request con contexto para permitir cancelación
	req, err := http.NewRequestWithContext(ctx, http.MethodGet, p.apiURL, nil)
	if err != nil {
		return nil, fmt.Errorf("failed to create HTTP request: %w", err)
	}

	// Establecer headers apropiados
	req.Header.Set("Accept", "application/json")
	req.Header.Set("Content-Type", "application/json")

	// Ejecutar la solicitud HTTP
	resp, err := p.httpClient.Do(req)
	if err != nil {
		return nil, fmt.Errorf("failed to execute HTTP request: %w", err)
	}
	defer resp.Body.Close()

	// Verificar código de estado HTTP
	if resp.StatusCode != http.StatusOK {
		return nil, fmt.Errorf("unexpected HTTP status code: %d", resp.StatusCode)
	}

	// Leer el cuerpo de la respuesta
	body, err := io.ReadAll(resp.Body)
	if err != nil {
		return nil, fmt.Errorf("failed to read response body: %w", err)
	}

	// Deserializar JSON a slice de libros
	var books []models.Book
	if err := json.Unmarshal(body, &books); err != nil {
		return nil, fmt.Errorf("failed to parse JSON response: %w", err)
	}

	return books, nil
}

// CountBooksByAuthor cuenta cuántos libros fueron escritos por un autor específico
// La búsqueda es case-sensitive para mantener consistencia
func (s *booksService) CountBooksByAuthor(ctx context.Context, author string) (uint, error) {
	books, err := s.booksProvider.GetBooks(ctx)
	if err != nil {
		return 0, fmt.Errorf("provider error: %w", err)
	}
	
	var count uint
	for _, book := range books {
		if book.Author == author {
			count++
		}
	}
	
	return count, nil
}

// GetCheapestBook encuentra el libro con el precio más bajo
// Retorna el nombre del libro más barato o error si no hay libros
func (s *booksService) GetCheapestBook(ctx context.Context) (string, error) {
	books, err := s.booksProvider.GetBooks(ctx)
	if err != nil {
		return "", fmt.Errorf("provider error: %w", err)
	}
	
	if len(books) == 0 {
		return "", ErrNoBooksAvailable
	}

	cheapest := slices.MinFunc(books, func(a, b models.Book) int {
		return int(a.Price - b.Price)
	})
	
	return cheapest.Name, nil
}

// GetMeanUnitsSold calcula el promedio de unidades vendidas de todos los libros
// Retorna error si no hay libros disponibles para evitar división por cero
func (s *booksService) GetMeanUnitsSold(ctx context.Context) (uint, error) {
	books, err := s.booksProvider.GetBooks(ctx)
	if err != nil {
		return 0, fmt.Errorf("provider error: %w", err)
	}
	
