	// Test 1: URL inválida (genera error de conexión)
	fmt.Println("=== Test 1: URL Inválida ===")
	invalidProvider := providers.NewHTTPBooksProviderWithConfig(
		"http://localhost:9999/nonexistent",
		&http.Client{Timeout: 2 * time.Second},
	)
	service1 := services.NewBooksService(invalidProvider)

	result, err := service1.GetMeanUnitsSold(context.Background())
	if err != nil {
		fmt.Printf("❌ Error (esperado): %v\n", err)
		fmt.Printf("Resultado: %d\n\n", result)
	}

	// Test 2: Timeout (genera error de timeout)
	fmt.Println("=== Test 2: Timeout ===")
	timeoutProvider := providers.NewHTTPBooksProviderWithConfig(
		"https://httpstat.us/200?sleep=5000", // Demora 5 segundos
		&http.Client{Timeout: 1 * time.Second}, // Timeout de 1 segundo
	)
